    let manifest = crate::reviewer::canaries::CanaryEvidenceManifest::with_generated_at(
        "1000.000000000Z",
        Some(model_provider),
        vec![snapshot, artifact],
    );
    let fresh =
        crate::reviewer::canaries::CanaryEvidenceFreshnessPolicy::at("1100.000000000Z", 120);
