    self
}

    pub fn allows_provider_resource(
        &self,
        provider_id: &ToolProviderId,
        resource_id: &ProviderResourceId,
    ) -> bool {
        match &self.allowed_provider_resources {
            Some(allowed) => allowed.iter().any(|scope| {
