pub enum ReviewEvent {
    RunStarted {
        snapshot_id: SnapshotId,
    },
    SnapshotStarted {
        snapshot_id: SnapshotId,
    },
    RepoManifestCompleted {
        files: usize,
        skipped: usize,
        bytes: u64,
        ms: u64,
    },
    SessionStarted {
        session_id: String,
    },
    ModelStarted {
        session_id: String,
        turn: u32,
    },
    ModelCompleted {
        session_id: String,
        turn: u32,
        tool_call_count: usize,
    },
    ToolBatchStarted {
        session_id: String,
        turn: u32,
        count: usize,
    },
    ToolCallCompleted {
        call_id: String,
        tool_id: String,
        ok: bool,
        error_code: Option<ToolErrorCode>,
    },
    ToolCallDenied {
        call_id: String,
        tool_id: String,
        error_code: ToolErrorCode,
        reason: String,
    },
    ArtifactCreated {
        artifact_id: ArtifactId,
        tool_call_id: String,
