impl RemoteArtifactObjectStore {
    pub fn new(
        base_uri: impl Into<String>,
        client: Arc<dyn RemoteArtifactObjectClient>,
    ) -> RuntimeResult<Self> {
        Ok(Self {
            base_uri: normalize_remote_store_base_uri(base_uri.into(), "artifact")?,
            client,
        })
    }

