    if content_hash.len() != 64 || !content_hash.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(RuntimeError::RepoAccessDenied);
    }
    Ok(root
        .join(artifact_view_name(view))
        .join(&content_hash[..2])
        .join(format!("{content_hash}.txt")))
}

