pub enum ReviewConclusion {
    Approved,
    Commented,
    ChangesRequested,
}

impl ReviewConclusion {
    fn from_findings(findings: &[ReviewFinding]) -> Self {
        if findings
            .iter()
            .any(|finding| finding.severity == ReviewFindingSeverity::Error)
        {
            return Self::ChangesRequested;
        }
        if findings.is_empty() {
            Self::Approved
        } else {
            Self::Commented
        }
    }
}

